using System.ComponentModel.DataAnnotations;

namespace RecipeShare.Models;

public class Recipe
{
    public int Id { get; set; }
    public string Title { get; set; } = "";
    public string Category { get; set; } = "";
    public string Description { get; set; } = "";
    public List<string> Ingredients { get; set; } = [];
    public List<string> Steps { get; set; } = [];
    public int TotalRatings { get; set; }
    public int RatingSum { get; set; }
    public double AverageRating => TotalRatings > 0 ? (double)RatingSum / TotalRatings : 0;
}

public class RecipeSubmission
{
    [Required(ErrorMessage = "Title is required.")]
    [StringLength(100, ErrorMessage = "Title must be 100 characters or fewer.")]
    public string Title { get; set; } = "";

    [Required(ErrorMessage = "Category is required.")]
    public string Category { get; set; } = "";

    [Required(ErrorMessage = "Enter at least one ingredient.")]
    [MinLength(1, ErrorMessage = "Enter at least one ingredient.")]
    public string Ingredients { get; set; } = "";

    [Required(ErrorMessage = "Enter at least one step.")]
    [MinLength(1, ErrorMessage = "Enter at least one step.")]
    public string Steps { get; set; } = "";

    [StringLength(300, ErrorMessage = "Description must be 300 characters or fewer.")]
    public string Description { get; set; } = "";
}

using RecipeShare.Models;

namespace RecipeShare.Services;

public class RecipeService
{
    private readonly List<Recipe> _recipes;
    private int _nextId;

    public RecipeService()
    {
        _recipes =
        [
            new()
            {
                Id = 1, Title = "Classic Pancakes", Category = "Breakfast",
                Description = "Fluffy golden pancakes perfect for a weekend morning.",
                Ingredients = ["2 cups flour", "2 eggs", "1½ cups milk", "3 tbsp sugar", "1 tsp baking powder", "Pinch of salt", "Butter for cooking"],
                Steps = ["Mix dry ingredients in a bowl.", "Whisk eggs and milk together, then combine with dry ingredients.", "Heat a buttered pan over medium heat.", "Pour ¼ cup batter per pancake and cook until bubbles form.", "Flip and cook until golden brown."],
                TotalRatings = 12, RatingSum = 50
            },
            new()
            {
                Id = 2, Title = "Spaghetti Carbonara", Category = "Pasta",
                Description = "A rich and creamy Italian classic made with eggs, cheese, and pancetta.",
                Ingredients = ["400g spaghetti", "200g pancetta", "4 egg yolks", "1 cup Pecorino Romano", "Black pepper"],
                Steps = ["Cook spaghetti in salted boiling water.", "Fry pancetta until crispy.", "Whisk egg yolks with cheese and pepper.", "Drain pasta, toss with pancetta.", "Remove from heat, stir in egg mixture until creamy."],
                TotalRatings = 20, RatingSum = 90
            },
            new()
            {
                Id = 3, Title = "Caesar Salad", Category = "Salads",
                Description = "Crisp romaine with a tangy homemade Caesar dressing.",
                Ingredients = ["1 head romaine lettuce", "½ cup croutons", "¼ cup Parmesan", "2 tbsp Caesar dressing", "Lemon juice"],
                Steps = ["Wash and chop romaine lettuce.", "Toss lettuce with Caesar dressing.", "Top with croutons and shaved Parmesan.", "Squeeze fresh lemon juice on top and serve."],
                TotalRatings = 8, RatingSum = 30
            },
            new()
            {
                Id = 4, Title = "Chocolate Lava Cake", Category = "Desserts",
                Description = "Decadent individual cakes with a molten chocolate center.",
                Ingredients = ["200g dark chocolate", "100g butter", "3 eggs", "¼ cup sugar", "2 tbsp flour"],
                Steps = ["Melt chocolate and butter together.", "Whisk eggs and sugar until thick.", "Fold chocolate mixture into eggs, then fold in flour.", "Pour into greased ramekins.", "Bake at 220°C for 12 minutes. Center should be soft."],
                TotalRatings = 15, RatingSum = 72
            },
            new()
            {
                Id = 5, Title = "Grilled Chicken Tacos", Category = "Main Courses",
                Description = "Juicy grilled chicken with fresh toppings in warm tortillas.",
                Ingredients = ["500g chicken breast", "8 small tortillas", "1 avocado", "Salsa", "Lime", "Cilantro", "Salt and cumin"],
                Steps = ["Season chicken with salt, cumin, and lime juice.", "Grill chicken until cooked through, then slice.", "Warm tortillas on the grill.", "Assemble tacos with chicken, avocado, salsa, and cilantro."],
                TotalRatings = 18, RatingSum = 80
            },
            new()
            {
                Id = 6, Title = "Mushroom Risotto", Category = "Main Courses",
                Description = "Creamy Arborio rice with sautéed mushrooms and Parmesan.",
                Ingredients = ["1½ cups Arborio rice", "300g mixed mushrooms", "4 cups chicken broth", "½ cup white wine", "½ cup Parmesan", "1 onion", "2 cloves garlic", "Butter"],
                Steps = ["Sauté onion and garlic in butter.", "Add mushrooms and cook until golden.", "Add rice and toast for 2 minutes.", "Add wine and stir until absorbed.", "Add broth one ladle at a time, stirring until absorbed.", "Stir in Parmesan and serve."],
                TotalRatings = 10, RatingSum = 45
            },
            new()
            {
                Id = 7, Title = "Berry Smoothie Bowl", Category = "Breakfast",
                Description = "A thick, fruity smoothie topped with granola and fresh berries.",
                Ingredients = ["1 cup mixed frozen berries", "1 banana", "½ cup yogurt", "Granola", "Fresh berries for topping", "Honey"],
                Steps = ["Blend frozen berries, banana, and yogurt until thick.", "Pour into a bowl.", "Top with granola, fresh berries, and a drizzle of honey."],
                TotalRatings = 6, RatingSum = 26
            },
            new()
            {
                Id = 8, Title = "Tomato Basil Soup", Category = "Soups",
                Description = "A comforting classic made with ripe tomatoes and fresh basil.",
                Ingredients = ["6 ripe tomatoes", "1 onion", "3 cloves garlic", "Fresh basil", "2 cups vegetable broth", "Cream", "Olive oil"],
                Steps = ["Sauté onion and garlic in olive oil.", "Add chopped tomatoes and broth. Simmer 20 minutes.", "Blend until smooth.", "Stir in cream and torn basil leaves.", "Season and serve with crusty bread."],
                TotalRatings = 9, RatingSum = 38
            },
        ];
        _nextId = _recipes.Max(r => r.Id) + 1;
    }

    public IReadOnlyList<string> GetCategories()
    {
        return _recipes.Select(r => r.Category).Distinct().Order().ToList();
    }

    public IReadOnlyList<Recipe> GetByCategory(string category)
    {
        return _recipes.Where(r => r.Category.Equals(category, StringComparison.OrdinalIgnoreCase)).ToList();
    }

    public Recipe? GetById(int id)
    {
        return _recipes.FirstOrDefault(r => r.Id == id);
    }

    public void AddRating(int recipeId, int stars)
    {
        var recipe = GetById(recipeId);
        if (recipe is not null && stars is >= 1 and <= 5)
        {
            recipe.TotalRatings++;
            recipe.RatingSum += stars;
        }
    }

    public Recipe AddRecipe(RecipeSubmission submission)
    {
        var recipe = new Recipe
        {
            Id = _nextId++,
            Title = submission.Title.Trim(),
            Category = submission.Category.Trim(),
            Description = submission.Description.Trim(),
            Ingredients = submission.Ingredients
                .Split('\n', StringSplitOptions.RemoveEmptyEntries | StringSplitOptions.TrimEntries)
                .ToList(),
            Steps = submission.Steps
                .Split('\n', StringSplitOptions.RemoveEmptyEntries | StringSplitOptions.TrimEntries)
                .ToList(),
        };
        _recipes.Add(recipe);
        return recipe;
    }
}

