@page "/category/{CategoryName}"
@inject RecipeService RecipeService

<PageTitle>@CategoryName Recipes — RecipeShare</PageTitle>

<h1>@CategoryName Recipes</h1>
<nav aria-label="breadcrumb">
    <ol class="breadcrumb">
        <li class="breadcrumb-item"><a href="/">Home</a></li>
        <li class="breadcrumb-item active">@CategoryName</li>
    </ol>
</nav>

@if (recipes.Count == 0)
{
    <div class="alert alert-info">No recipes found in this category.</div>
}
else
{
    <div class="row">
        @foreach (var recipe in recipes)
        {
            <div class="col-md-6 mb-3">
                <div class="card h-100">
                    <div class="card-body">
                        <h5 class="card-title">@recipe.Title</h5>
                        <p class="card-text">@recipe.Description</p>
                        <p class="text-muted mb-2">
                            @if (recipe.TotalRatings > 0)
                            {
                                <span>⭐ @recipe.AverageRating.ToString("F1") (@recipe.TotalRatings ratings)</span>
                            }
                            else
                            {
                                <span>No ratings yet</span>
                            }
                        </p>
                        <a href="@($"recipe/{recipe.Id}")" class="btn btn-primary">View Recipe</a>
                    </div>
                </div>
            </div>
        }
    </div>
}

@code {
    [Parameter] public string CategoryName { get; set; } = "";

    private IReadOnlyList<Recipe> recipes = [];

    protected override void OnParametersSet()
    {
        recipes = RecipeService.GetByCategory(CategoryName);
    }
}

@page "/recipe/{Id:int}"
@inject RecipeService RecipeService

<PageTitle>@(recipe?.Title ?? "Recipe") — RecipeShare</PageTitle>

@if (recipe is null)
{
    <div class="alert alert-warning">Recipe not found.</div>
}
else
{
    <nav aria-label="breadcrumb">
        <ol class="breadcrumb">
            <li class="breadcrumb-item"><a href="/">Home</a></li>
            <li class="breadcrumb-item"><a href="@($"category/{Uri.EscapeDataString(recipe.Category)}")">@recipe.Category</a></li>
            <li class="breadcrumb-item active">@recipe.Title</li>
        </ol>
    </nav>

    <h1>@recipe.Title</h1>
    <p class="lead">@recipe.Description</p>

    <StarRating RecipeId="recipe.Id" @rendermode="InteractiveServer" />

    <h3 class="mt-4">Ingredients</h3>
    <ul>
        @foreach (var ingredient in recipe.Ingredients)
        {
            <li>@ingredient</li>
        }
    </ul>

    <h3>Steps</h3>
    <ol>
        @foreach (var step in recipe.Steps)
        {
            <li class="mb-2">@step</li>
        }
    </ol>
}

@code {
    [Parameter] public int Id { get; set; }

    private Recipe? recipe;

    protected override void OnParametersSet()
    {
        recipe = RecipeService.GetById(Id);
    }
}

@inject RecipeService RecipeService

<div class="my-3 p-3 border rounded bg-light">
    <h5>Rate this recipe</h5>
    <div class="d-flex align-items-center gap-1 mb-2">
        @for (int i = 1; i <= 5; i++)
        {
            var star = i;
            <button class="btn btn-link p-0 fs-4 text-decoration-none"
                    @onclick="() => SubmitRating(star)"
                    disabled="@hasRated"
                    title="@($"Rate {star} star{(star > 1 ? "s" : "")}")">
                @(star <= displayStars ? "★" : "☆")
            </button>
        }
    </div>

    @if (hasRated)
    {
        <div class="alert alert-success py-1 px-2 d-inline-block">
            Thanks for rating! You gave @userRating star@(userRating > 1 ? "s" : "").
        </div>
    }

    <p class="text-muted mb-0">
        @if (recipe is not null && recipe.TotalRatings > 0)
        {
            <span>Average: @recipe.AverageRating.ToString("F1") ⭐ (@recipe.TotalRatings ratings)</span>
        }
        else
        {
            <span>No ratings yet — be the first!</span>
        }
    </p>
</div>

@code {
    [Parameter] public int RecipeId { get; set; }

    private Recipe? recipe;
    private int displayStars;
    private int userRating;
    private bool hasRated;

    protected override void OnParametersSet()
    {
        recipe = RecipeService.GetById(RecipeId);
        displayStars = recipe is not null ? (int)Math.Round(recipe.AverageRating) : 0;
    }

    private void SubmitRating(int stars)
    {
        if (hasRated) return;

        RecipeService.AddRating(RecipeId, stars);
        userRating = stars;
        displayStars = stars;
        hasRated = true;
        recipe = RecipeService.GetById(RecipeId);
    }
}

@page "/submit"
@rendermode InteractiveServer
@inject RecipeService RecipeService
@inject NavigationManager Navigation

<PageTitle>Submit a Recipe — RecipeShare</PageTitle>

<h1>📝 Submit a Recipe</h1>
