    <DataAnnotationsValidator />
    <ValidationSummary class="text-danger" />

    <div class="mb-3">
        <label for="title" class="form-label">Recipe Title</label>
        <InputText id="title" class="form-control" @bind-Value="submission.Title" placeholder="e.g. Grandma's Apple Pie" />
        <ValidationMessage For="() => submission.Title" class="text-danger" />
    </div>

    <div class="mb-3">
        <label for="category" class="form-label">Category</label>
        <InputSelect id="category" class="form-select" @bind-Value="submission.Category">
            <option value="">— Select a category —</option>
            <option value="Breakfast">Breakfast</option>
            <option value="Main Courses">Main Courses</option>
            <option value="Pasta">Pasta</option>
            <option value="Salads">Salads</option>
            <option value="Soups">Soups</option>
            <option value="Desserts">Desserts</option>
        </InputSelect>
        <ValidationMessage For="() => submission.Category" class="text-danger" />
    </div>

    <div class="mb-3">
        <label for="description" class="form-label">Short Description</label>
        <InputText id="description" class="form-control" @bind-Value="submission.Description" placeholder="A brief description of your recipe" />
        <ValidationMessage For="() => submission.Description" class="text-danger" />
    </div>

    <div class="mb-3">
        <label for="ingredients" class="form-label">Ingredients (one per line)</label>
        <InputTextArea id="ingredients" class="form-control" rows="5" @bind-Value="submission.Ingredients"
                       placeholder="2 cups flour&#10;3 eggs&#10;1 cup sugar" />
        <ValidationMessage For="() => submission.Ingredients" class="text-danger" />
    </div>

    <div class="mb-3">
        <label for="steps" class="form-label">Steps (one per line)</label>
        <InputTextArea id="steps" class="form-control" rows="5" @bind-Value="submission.Steps"
                       placeholder="Preheat oven to 350°F&#10;Mix dry ingredients&#10;Bake for 30 minutes" />
        <ValidationMessage For="() => submission.Steps" class="text-danger" />
    </div>

    <button type="submit" class="btn btn-primary">Submit Recipe</button>
</EditForm>

@code {
    private RecipeSubmission submission = new();
    private bool submitted;
    private string submittedTitle = "";
    private int submittedId;

    private void HandleSubmit()
    {
        var recipe = RecipeService.AddRecipe(submission);
        submittedTitle = recipe.Title;
        submittedId = recipe.Id;
        submitted = true;
        submission = new();
    }
}

